// Validate input. Name is required; phone is optional
// (a name-only row still makes the patient searchable, the phone is filled in later).
const body = $input.first().json.body || {};

// --- Patient matching helpers (same logic in upsert + recovery) ---
// Strip leading status icons (⏳ ✅ 🔔 ...) and stray punctuation from a name
function cleanName(n) {
  return String(n || '')
    .replace(/^[^\p{L}\p{N}]+/u, '')
    .replace(/\s+/g, ' ')
    .replace(/[\s.,;:\-]+$/, '')
    .trim();
}
function nameKey(n) {
  return cleanName(n).toLowerCase();
}
// Normalize to +359 international format (text-safe for Google Sheets)
function toInternational(p) {
  let phone = String(p || '').replace(/[\s()\-.\/]/g, '');
  if (!phone) return '';
  if (phone.startsWith('00359')) phone = '+359' + phone.slice(5);
  else if (phone.startsWith('359')) phone = '+' + phone;
  else if (phone.startsWith('0') && phone.length >= 10) phone = '+359' + phone.slice(1);
  else if (/^[89]\d{8}$/.test(phone)) phone = '+359' + phone;
  else if (!phone.startsWith('+') && phone.length >= 9) phone = '+359' + phone;
  return phone;
}
// Core digits for comparison: +359887493315 / 0887493315 / 887493315 -> 887493315
function phoneKey(p) {
  return String(p || '').replace(/\D/g, '').replace(/^00/, '').replace(/^359/, '').replace(/^0/, '');
}
function isBlockName(n) {
  return /блокиран|почивка|отпуск|blocked/i.test(String(n || ''));
}

const name = cleanName(body.name);
if (!name) {
  return [{ json: { valid: false, error: 'Липсва име' } }];
}
if (isBlockName(name)) {
  return [{ json: { valid: false, error: 'Блокиран час, не е пациент' } }];
}

const phone = toInternational(body.phone);
const email = String(body.email || '').trim();

// Optional notification preferences (sms | email | viber | telegram)
let notify = [];
if (Array.isArray(body.notify)) notify = body.notify;
else if (typeof body.notify === 'string') notify = body.notify.split(',').map(s => s.trim()).filter(Boolean);
const allowed = ['sms', 'email', 'viber', 'telegram'];
notify = notify.filter(c => allowed.includes(c));

return [{ json: { valid: true, name, phone, email, notify: notify.join(',') } }];

// Decide what to do with the incoming patient: create, update or skip.
// Rules:
//  - same name + same phone            -> skip (only fill missing email/notify)
//  - same name, row without phone      -> update that row with the phone
//  - same name (single row), new phone -> update phone (patient changed number)
//  - same phone, different name        -> create (family members share phones)
//  - unknown name                      -> create
const input = $('Validate Input').first().json;
const rows = $('Read Patients').all()
  .map(i => i.json)
  .filter(r => r && r.row_number && (r.name || r.phone));

// --- Patient matching helpers (same logic in upsert + recovery) ---
// Strip leading status icons (⏳ ✅ 🔔 ...) and stray punctuation from a name
function cleanName(n) {
  return String(n || '')
    .replace(/^[^\p{L}\p{N}]+/u, '')
    .replace(/\s+/g, ' ')
    .replace(/[\s.,;:\-]+$/, '')
    .trim();
}
function nameKey(n) {
  return cleanName(n).toLowerCase();
}
// Normalize to +359 international format (text-safe for Google Sheets)
function toInternational(p) {
  let phone = String(p || '').replace(/[\s()\-.\/]/g, '');
  if (!phone) return '';
  if (phone.startsWith('00359')) phone = '+359' + phone.slice(5);
  else if (phone.startsWith('359')) phone = '+' + phone;
  else if (phone.startsWith('0') && phone.length >= 10) phone = '+359' + phone.slice(1);
  else if (/^[89]\d{8}$/.test(phone)) phone = '+359' + phone;
  else if (!phone.startsWith('+') && phone.length >= 9) phone = '+359' + phone;
  return phone;
}
// Core digits for comparison: +359887493315 / 0887493315 / 887493315 -> 887493315
function phoneKey(p) {
  return String(p || '').replace(/\D/g, '').replace(/^00/, '').replace(/^359/, '').replace(/^0/, '');
}
function isBlockName(n) {
  return /блокиран|почивка|отпуск|blocked/i.test(String(n || ''));
}

const inKey = nameKey(input.name);
const inPhone = phoneKey(input.phone);
const sameName = rows.filter(r => nameKey(r.name) === inKey);

function merged(row, action, extra = {}) {
  return {
    action,
    rowNumber: row.row_number,
    name: row.name,
    phone: input.phone || String(row.phone || '').replace(/^'/, ''),
    email: input.email || row.email || '',
    notify: input.notify || row.notify || '',
    ...extra
  };
}

let result;
const exact = inPhone
  ? sameName.find(r => phoneKey(r.phone) === inPhone)
  : sameName[0];

if (exact) {
  const needEmail = input.email && input.email !== String(exact.email || '');
  const needNotify = input.notify && input.notify !== String(exact.notify || '');
  result = (needEmail || needNotify)
    ? merged(exact, 'updated')
    : { action: 'skipped', name: exact.name, phone: String(exact.phone || '') };
} else if (inPhone && sameName.length > 0) {
  const noPhoneRow = sameName.find(r => !phoneKey(r.phone));
  if (noPhoneRow) {
    result = merged(noPhoneRow, 'updated', { previousPhone: '' });
  } else if (sameName.length === 1) {
    result = merged(sameName[0], 'updated', { previousPhone: String(sameName[0].phone || '') });
  } else {
    // Several different people with this name and none has this phone -> new person
    result = { action: 'created', name: input.name, phone: input.phone, email: input.email, notify: input.notify };
  }
} else {
  result = { action: 'created', name: input.name, phone: input.phone, email: input.email, notify: input.notify };
}

return [{ json: result }];
